SELECT s.region, DATE_TRUNC('MONTH', s.opened_date) AS opened_month, SUM(CASE WHEN o.status = 'SHIPPED' THEN 1 ELSE 0 END) AS shipped_count, SUM(o.shipping_fee) AS total_shipping_fee FROM orders o INNER JOIN customers c ON c.id = o.customer_id INNER JOIN stores s ON s.id = o.store_id GROUP BY s.region, DATE_TRUNC('MONTH', s.opened_date) HAVING SUM(CASE WHEN o.status = 'SHIPPED' THEN 1 ELSE 0 END) > 66;
